import { Table, StringColumn, BooleanColumn, IntegerColumn, ChoiceColumn } from '@servicenow/sdk/core'

export const x_test_complex_table = Table({
    actions: ['read', 'update', 'delete', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowWebServiceAccess: true,
    audit: true,
    extends: 'task',
    extensible: true,
    label: 'Complex Test Table',
    name: 'x_test_complex_table',
    schema: {
        title: StringColumn({
            label: 'Title',
            mandatory: true,
            maxLength: 100,
            spellCheck: true,
            textIndex: true,
            unique: true,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        priority: IntegerColumn({
            default: '3',
            label: [
                {
                    label: 'Priority',
                    plural: 'Priority Values',
                },
            ],
        }),
        status: ChoiceColumn({
            choices: {
                new: {
                    label: 'New',
                    sequence: 10,
                },
                in_progress: {
                    label: 'In Progress',
                    sequence: 20,
                },
                complete: {
                    label: 'Complete',
                    sequence: 30,
                },
                cancelled: {
                    label: 'Cancelled',
                    sequence: 40,
                    inactive: true,
                },
            },
            label: 'Status',
        }),
        readonly_field: StringColumn({
            label: 'Read Only Field',
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
    },
    scriptableTable: true,
    textIndex: true,
})
